const d = $input.first().json;
const missing = [];

if (!d.briefing) missing.push('briefing aprobado');
if (!d.design_option) missing.push('opción de diseño seleccionada');
if (!d.cost_estimate) missing.push('estimación de costes');
if (!d.trade_assignments || d.trade_assignments.length === 0) missing.push('asignaciones de gremios');

const preflight_passed = missing.length === 0;

return [{ json: { ...d, preflight_passed, missing_items: missing } }];

const project = $('Preflight Check').first().json;
const createExec = $('Create Execution').first().json;
const execution_id = createExec.id;
const dbPrompt = $input.first().json;

const briefing = typeof project.briefing === 'string' ? JSON.parse(project.briefing) : (project.briefing || {});
const design = typeof project.design_option === 'string' ? JSON.parse(project.design_option) : (project.design_option || {});
const costs = typeof project.cost_estimate === 'string' ? JSON.parse(project.cost_estimate) : (project.cost_estimate || {});
const trades = Array.isArray(project.trade_assignments) ? project.trade_assignments : [];
const breakdown = Array.isArray(costs.breakdown) ? costs.breakdown : [];

const tradesList = trades.map(t =>
  `- ${t.trade_type || t.specialty}: ${t.scope_description || 'alcance por confirmar'}`
).join('\n');

const partidas = breakdown.slice(0, 15).map(p =>
  `- ${p.partida || p.description || 'Partida'}: ${p.importe || p.amount || '?'}€`
).join('\n');

const objetivos = Array.isArray(briefing.objectives) ? briefing.objectives.join('; ') : (briefing.objectives || '');
const constraints = Array.isArray(briefing.constraints) ? briefing.constraints.join('; ') : '';

const prompt_system_fallback = `Eres un jefe de obra experto en reformas de vivienda en España con más de 20 años de experiencia coordinando proyectos de rehabilitación.
Genera un plan de trabajo detallado y realista para el proyecto de reforma que se describe.
Devuelve ÚNICAMENTE un objeto JSON válido, sin texto adicional antes ni después.

El JSON debe seguir esta estructura exacta:
{
  "total_weeks": number,
  "phases": [
    {
      "order": number,
      "phase_name": string,
      "specialty": string,
      "duration_weeks": number,
      "dependencies": number[],
      "notes": string
    }
  ],
  "milestones": [
    {"week": number, "description": string}
  ],
  "critical_path": string[],
  "notes": string
}

Reglas:
- Ordena las fases en secuencia técnica correcta: demolición → obra civil → instalaciones ocultas → tabiquería → acabados → equipamiento
- Las dependencias son los números 'order' de fases que deben completarse antes
- La duración se basa en el área del inmueble (${project.property_area_m2 || '?'} m²)
- Incluye al menos 4 hitos: inicio de obra, fin de trabajos estructurales, inicio de acabados, entrega
- critical_path lista los nombres de las fases cuyo retraso retrasa la entrega total
- Pinturas y acabados son siempre las últimas fases`;
// === STUDIO PROFILE INJECTION (B24) ===
const _studio = $('Load Studio Profile').first().json || {};
function _safeStudio(v){ if(v==null)return null; if(typeof v==='string'){try{return JSON.parse(v);}catch(e){return v;}} return v; }
const _id=_safeStudio(_studio.identity)||{},_priorities=_safeStudio(_studio.priorities)||[],_redLines=_safeStudio(_studio.red_lines)||[];
const _SP_PLAN_LINES=[];
_SP_PLAN_LINES.push('Estudio: '+(_id.nombre_estudio||'estudio')+' en '+(_id.ciudad||'Espana')+'.');
_SP_PLAN_LINES.push('PRIORIDADES (orden estricto al planificar fases y rutas criticas):');
(_priorities||[]).forEach(p=>_SP_PLAN_LINES.push((p.orden||'?')+'. '+(p.prioridad||'')+(p.detalle?' - '+p.detalle:'')));
_SP_PLAN_LINES.push('LINEAS ROJAS:');
(_redLines||[]).forEach(l=>_SP_PLAN_LINES.push('- '+(l.texto||'')));
const _SP_PLAN=_SP_PLAN_LINES.join('\n');
// === END STUDIO PROFILE INJECTION ===
const prompt_system = _SP_PLAN + '\n\n' + ((dbPrompt && dbPrompt.content) ? dbPrompt.content : prompt_system_fallback);

const prompt_user = `PROYECTO: ${project.project_name}
Tipo: ${project.project_type} | Área: ${project.property_area_m2} m²
Ubicación: ${project.location_city}, ${project.location_province}
Tipo propiedad: ${project.property_type || 'piso'}
Presupuesto: ${costs.total_estimated || costs.total_amount || '?'}€

TRABAJOS POR GREMIO:
${tradesList || 'Sin asignaciones registradas'}

PRINCIPALES PARTIDAS:
${partidas || 'Sin desglose disponible'}

OBJETIVOS: ${objetivos || 'Sin especificar'}
${constraints ? '\nCONDICIONANTES: ' + constraints : ''}

Genera el plan de trabajo en JSON.`;

return [{
  json: {
    ...project,
    execution_id,
    prompt_system,
    prompt_user,
    model: 'gpt-4o',
    temperature: 0.3,
    project_id: project.id,
    agent_name: 'agent_planner'
  }
}];

const project = $('Build Plan Prompt').first().json;
const llm = $input.first().json;
const text = llm.text || '';

let plan = {};
let parse_error = null;

try {
  const match = text.match(/\{[\s\S]*\}/);
  if (!match) throw new Error('No JSON object found in LLM response');
  plan = JSON.parse(match[0]);
} catch(e) {
  parse_error = e.message;
  plan = {
    total_weeks: 8,
    phases: [],
    milestones: [
      { week: 0, description: 'Inicio de obra' },
      { week: 8, description: 'Entrega de obra' }
    ],
    critical_path: [],
    notes: 'Plan con valores por defecto — error al parsear: ' + e.message
  };
}

const totalWeeks = plan.total_weeks || 8;
const totalDays = totalWeeks * 7;

return [{
  json: {
    project_id: project.id,
    execution_id: project.execution_id,
    project_name: project.project_name,
    total_duration_days: totalDays,
    total_weeks: totalWeeks,
    phases_count: (plan.phases || []).length,
    phases_json: JSON.stringify(plan.phases || []),
    milestones_json: JSON.stringify(plan.milestones || []),
    critical_path_json: JSON.stringify(plan.critical_path || []),
    plan_notes: plan.notes || '',
    parse_error: parse_error || null
  }
}];
